package com.dbmmap.core.mapping;

/**
 * Custom ClassLoader for dynamically generated mapper classes.
 * <p>
 * Extends ClassLoader to provide a public defineClass method
 * for loading dynamically generated bytecode.
 * </p>
 *
 * @author dbmmap
 * @since 1.0.0
 */
public class MapperClassLoader extends ClassLoader {

    /**
     * Constructs a MapperClassLoader with the default parent class loader.
     */
    public MapperClassLoader() {
        super();
    }

    /**
     * Constructs a MapperClassLoader with a specified parent class loader.
     *
     * @param parent the parent class loader
     */
    public MapperClassLoader(ClassLoader parent) {
        super(parent);
    }

    /**
     * Defines a class from bytecode.
     * <p>
     * This method exposes the protected defineClass method for use
     * with dynamically generated mapper classes. If a class with the
     * same name is already defined, the existing class is returned.
     * </p>
     *
     * @param name the fully qualified class name
     * @param bytes the bytecode of the class
     * @return the defined Class object
     * @throws ClassFormatError if the bytecode is invalid
     */
    public Class<?> defineClass(String name, byte[] bytes) {
        Class<?> existing = findLoadedClass(name);
        if (existing != null) {
            return existing;
        }
        return defineClass(name, bytes, 0, bytes.length);
    }
}